        ['Find the 8th term of the GP 5, −10, 20, …', ['1,280', '−640', '−70', '−9'], 'B', 'Tₙ = arⁿ⁻¹ = 5 × (−2)⁷.', 3],
        ['Find the 24th term of the AP 0, 4, 8, …', ['96', '0', '92', '88'], 'C', 'Tₙ = a + (n − 1)d = 0 + 23 × 4.', 3],
        ['Find the sum of the first 23 terms of the AP 12, 8, 4, …', ['−1,748', '−76', '−782', '−736'], 'D', 'Sₙ = n/2 [2a + (n − 1)d].', 4],
        ['2, 5, 8, 11 is an AP with common difference 3.', ['True', 'False'], 'A', 'd = 3.', 1, 'tf'],
        ['1, 2, 4, 8 is an AP.', ['True', 'False'], 'B', 'It is a GP with ratio 2.', 1, 'tf'],
        ['The sum to infinity exists for a GP with r = 2.', ['True', 'False'], 'B', 'It exists only when |r| < 1.', 3, 'tf'],
        ['In a GP, the common ratio is found by dividing a term by the previous term.', ['True', 'False'], 'A', 'r = T₂/T₁.', 2, 'tf'],
